package com.nahui.followupbussiness.identityaccess.adapter.in.rest;

import com.nahui.followupbussiness.identityaccess.application.port.in.LogoutSessionUseCase;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

class LogoutControllerTest {
 @Test void webPendingClearsOnlyHttpOnlyCookieAndReturnsNoContent() throws Exception {var use=mock(LogoutSessionUseCase.class);MockMvc mvc=MockMvcBuilders.standaloneSetup(new LogoutController(use,o->"https://web.test".equals(o))).build();mvc.perform(post("/auth/logout").header("X-Logout-Intent","PENDING").header("Origin","https://web.test").cookie(new jakarta.servlet.http.Cookie("__Host-fs-refresh","x".repeat(43)))).andExpect(status().isNoContent()).andExpect(header().string("Cache-Control","no-store")).andExpect(header().exists("X-Correlation-Id")).andExpect(header().string("Set-Cookie",org.hamcrest.Matchers.containsString("Max-Age=0")));var c=ArgumentCaptor.forClass(LogoutSessionUseCase.Command.class);verify(use).logout(c.capture());assertThat(c.getValue().webRefreshCookie()).hasSize(43);assertThat(c.getValue().allSessions()).isFalse();}
 @Test void mobilePendingUsesTicketWithoutBrowserAndReturnsNoContent() throws Exception {var use=mock(LogoutSessionUseCase.class);MockMvc mvc=MockMvcBuilders.standaloneSetup(new LogoutController(use,o->true)).build();mvc.perform(post("/auth/logout").header("X-Logout-Intent","PENDING").header("X-Session-Revocation-Ticket","t".repeat(43))).andExpect(status().isNoContent()).andExpect(header().string("Cache-Control","no-store"));verify(use).logout(any());}
 @Test void rejectedMobileTicketReturnsNeutralProblemWithoutEchoingTicket() throws Exception {var use=mock(LogoutSessionUseCase.class);String ticket="t".repeat(43);doThrow(new com.nahui.followupbussiness.identityaccess.application.LogoutSessionService.Rejected()).when(use).logout(any());MockMvc mvc=MockMvcBuilders.standaloneSetup(new LogoutController(use,o->true)).build();mvc.perform(post("/auth/logout").header("X-Logout-Intent","PENDING").header("X-Session-Revocation-Ticket",ticket)).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.code").value("LOGOUT_INVALID")).andExpect(jsonPath("$.detail").value("Request cannot be processed")).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString(ticket))));verify(use).logout(any());}
 @Test void mixedPendingCredentialsAreNeutralAndDoNotReachUseCase() throws Exception {var use=mock(LogoutSessionUseCase.class);MockMvc mvc=MockMvcBuilders.standaloneSetup(new LogoutController(use,o->true)).build();mvc.perform(post("/auth/logout").header("X-Logout-Intent","PENDING").header("Origin","https://web.test").header("X-Session-Revocation-Ticket","t".repeat(43)).cookie(new jakarta.servlet.http.Cookie("__Host-fs-refresh","x".repeat(43)))).andExpect(status().isBadRequest()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.code").value("LOGOUT_INVALID"));verifyNoInteractions(use);}
 @Test void normalBearerPassesInboundJwtFilterAndReachesDerivedActor() throws Exception {var use=mock(LogoutSessionUseCase.class);var auth=mock(com.nahui.followupbussiness.identityaccess.adapter.in.security.InboundJwtAuthenticator.class);var actor=new com.nahui.followupbussiness.identityaccess.domain.model.AuthenticatedActor(UUID.randomUUID(),UUID.randomUUID(),com.nahui.followupbussiness.identityaccess.domain.model.BaseRole.SELLER,UUID.randomUUID());when(auth.authenticate("valid")).thenReturn(org.springframework.security.authentication.UsernamePasswordAuthenticationToken.authenticated(actor,"valid",java.util.List.of()));MockMvc mvc=MockMvcBuilders.standaloneSetup(new LogoutController(use,o->true)).setCustomArgumentResolvers(new org.springframework.security.web.method.annotation.AuthenticationPrincipalArgumentResolver()).addFilters(new com.nahui.followupbussiness.identityaccess.adapter.in.security.InboundJwtAuthenticationFilter(auth,new com.nahui.followupbussiness.identityaccess.adapter.in.security.RestAuthenticationEntryPoint())).build();mvc.perform(post("/auth/logout").header("Authorization","Bearer valid").contentType(MediaType.APPLICATION_JSON).content("{\"allSessions\":false}")).andExpect(status().isNoContent()).andExpect(header().string("Cache-Control","no-store"));verify(use).logout(org.mockito.ArgumentMatchers.argThat(c->c.actor().equals(actor)));}
 @Test void webBearerLogoutForwardsCsrfAndPendingAuthorizationIsRejectedBeforeUseCase() throws Exception {var use=mock(LogoutSessionUseCase.class);var auth=mock(com.nahui.followupbussiness.identityaccess.adapter.in.security.InboundJwtAuthenticator.class);var actor=new com.nahui.followupbussiness.identityaccess.domain.model.AuthenticatedActor(UUID.randomUUID(),UUID.randomUUID(),com.nahui.followupbussiness.identityaccess.domain.model.BaseRole.SELLER,UUID.randomUUID());when(auth.authenticate("web")).thenReturn(org.springframework.security.authentication.UsernamePasswordAuthenticationToken.authenticated(actor,"web",java.util.List.of()));MockMvc mvc=MockMvcBuilders.standaloneSetup(new LogoutController(use,o->true)).setCustomArgumentResolvers(new org.springframework.security.web.method.annotation.AuthenticationPrincipalArgumentResolver()).addFilters(new com.nahui.followupbussiness.identityaccess.adapter.in.security.InboundJwtAuthenticationFilter(auth,new com.nahui.followupbussiness.identityaccess.adapter.in.security.RestAuthenticationEntryPoint())).build();mvc.perform(post("/auth/logout").header("Authorization","Bearer web").header("X-CSRF-Token","csrf").cookie(new jakarta.servlet.http.Cookie("__Host-fs-refresh","x".repeat(43))).contentType(MediaType.APPLICATION_JSON).content("{\"allSessions\":false}")).andExpect(status().isNoContent()).andExpect(header().string("Cache-Control","no-store"));verify(use).logout(org.mockito.ArgumentMatchers.argThat(c->"csrf".equals(c.csrfToken())&&c.actor().equals(actor)));reset(use);mvc.perform(post("/auth/logout").header("X-Logout-Intent","PENDING").header("Authorization","Bearer web").header("Origin","https://web.test").cookie(new jakarta.servlet.http.Cookie("__Host-fs-refresh","x".repeat(43)))).andExpect(status().isBadRequest());verifyNoInteractions(use);}
}
